BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=extensions,pg_catalog,public;
SELECT plan(21);
SELECT ok(to_regclass('app_private.admission_application_policy_snapshots') IS NOT NULL,'P44 retained policy source remains installed');
SELECT ok(to_regclass('app_private.admission_student_handoffs') IS NOT NULL,'P38 single-use handoff remains installed');
SELECT ok((SELECT count(*)=4 FROM pg_attribute WHERE attrelid='app_private.admission_student_handoffs'::regclass AND attname IN('policy_snapshot_id','admission_number_series_id','admission_numbering_profile_id','academic_year_id') AND attnotnull AND NOT attisdropped),'all four policy and number lineage fields are required');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_application_policy_snapshots'::regclass AND conname='db03_handoff_policy_snapshot_source_key' AND contype='u' AND cardinality(conkey)=6),'policy snapshot pins application version epoch profile and year');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_number_allocations'::regclass AND conname='db03_handoff_policy_allocation_source_key' AND contype='u' AND cardinality(conkey)=3),'allocation exposes exact application and source series');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_number_series'::regclass AND conname='db03_handoff_policy_series_source_key' AND contype='u' AND cardinality(conkey)=3),'series exposes exact numbering profile and academic year');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND conname='db03_handoff_policy_snapshot_same_application_version' AND contype='f' AND confrelid='app_private.admission_application_policy_snapshots'::regclass AND cardinality(conkey)=6),'handoff policy points to exact same application and stage epoch');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND conname='db03_handoff_policy_allocation_same_series' AND contype='f' AND confrelid='app_private.admission_number_allocations'::regclass AND cardinality(conkey)=3),'handoff number allocation has exact matching application and series');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND conname='db03_handoff_policy_series_exact_profile_year' AND contype='f' AND confrelid='app_private.admission_number_series'::regclass AND cardinality(conkey)=3),'handoff series must use the selected profile and academic year');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_policy_snapshot_same_application_version' AND pg_get_constraintdef(oid) LIKE '%application_version%' AND pg_get_constraintdef(oid) LIKE '%stage_epoch%'),'handoff cannot change the reviewed application version or epoch');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_policy_snapshot_same_application_version' AND pg_get_constraintdef(oid) LIKE '%admission_numbering_profile_id%' AND pg_get_constraintdef(oid) LIKE '%academic_year_id%'),'snapshot profile and academic year are part of the same key');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_policy_series_exact_profile_year' AND pg_get_constraintdef(oid) LIKE '%profile_id%' AND pg_get_constraintdef(oid) LIKE '%academic_year_id%'),'number series cannot come from another profile or school year');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_application_policy_snapshots'::regclass AND contype='f' AND confrelid='app_private.admission_applications'::regclass AND cardinality(conkey)=3),'P44 school and year scoped application FK still enforced');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND conname='db03_handoff_number_kind_exact'),'existing handoff still requires an ADMISSION number');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND conname='db03_handoff_number_state_exact'),'existing handoff still requires an allocated number');
SELECT ok((SELECT count(*)=1 FROM pg_class WHERE oid='app_private.admission_student_handoffs'::regclass AND relrowsecurity AND relforcerowsecurity),'handoff remains under forced RLS');
SELECT ok(NOT has_table_privilege('authenticated','app_private.admission_student_handoffs','INSERT') AND NOT has_table_privilege('schoolos_workflow_executor','app_private.admission_student_handoffs','INSERT'),'no client or workflow write privilege added');
SELECT throws_ok($q$INSERT INTO app_private.admission_student_handoffs DEFAULT VALUES$q$,'P0001','DB03 atomic Student handoff writer unavailable','handoff mutation fence remains active');
SELECT throws_ok($q$INSERT INTO app_private.admission_application_policy_snapshots DEFAULT VALUES$q$,'P0001','DB03 admission policy snapshot writer unavailable','policy snapshot mutation fence remains active');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_applications'::regclass AND conname='db03_unsubmitted_policy_null'),'existing draft policy projection is not silently unlocked');
SELECT ok(to_regprocedure('app.approve_admission_principal(uuid,bigint,uuid,uuid)') IS NULL,'Principal approval and Student creation remain unavailable');
SELECT * FROM finish();
ROLLBACK;
